/** What is typed on a pool's row to add a member. */
interface MemberInput {
  member: string;
  share: string;
  from: string;
  to: string;
}

/** A pool's total share, whether it is balanced, which members' dates leave out the sheet's today, and the cuts. */
interface Figures {
  total: number;
  balanced: boolean;
  outside: boolean[];
  cuts: number[] | null;
}

